using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Threading;using System.Web.Script.Serialization;
namespace PZ3D {
 // A connection owns transient choices and Buddy decisions; it never edits a live
 // configuration, a Steam JSON, or a frozen snapshot's execution contract.
 static class ServerLaunchSelection {
  internal sealed class Plan {internal string Mode;internal byte[] Original,Buddy;internal LauncherComponents.Row[] Rows;internal string[] Ids,Warnings;internal LaunchReadSet Evidence;}
  internal static string Mode(string value){if(string.IsNullOrEmpty(value))return "follow-server";if(value!="follow-server"&&value!="force-local")throw new IOException("服务器组件模式无效。");return value;}
  static string Id(string id){return id.TrimStart('\\');}
  static void ObserveMemory(Engine e,int memory,LaunchReadSet evidence){evidence.Expect(()=>{if(e.OwnedConfiguration.MemoryMb!=memory)throw new IOException("启动内存在连接准备期间改变，请重新连接。");});}
  internal static Plan Capture(Engine e,string mode,CancellationToken token){
   mode=Mode(mode);token.ThrowIfCancellationRequested();if(e.FrozenEnvironment!=null)SaveEnvironmentRuntime.ValidateOwnedRuntime(e);var budget=new LaunchReadBudget(67108864,100000);budget.Capture();budget.Checkpoint=(file,size)=>token.ThrowIfCancellationRequested();byte[] original=budget.Read(e.Mods,1048576);budget.Read(e.Config,4194304);if(e.OwnedLaunch){int memory=e.OwnedConfiguration.MemoryMb;ObserveMemory(e,memory,budget.Evidence);}string[] ids=e.OwnedLaunch?e.OwnedComponents().OrdinaryIds(token):SaveProfiles.DefaultMods(original);var warnings=new List<string>();var rows=new Dictionary<string,LauncherComponents.Row>(StringComparer.Ordinal);var evidence=budget.Evidence;
   bool vanilla=e.OwnedLaunch&&e.OwnedConfiguration.Mode=="vanilla";if(vanilla)ids=new string[0];
   var inspector=new LauncherComponents(LauncherConfiguration.Resolve(e.Data,e.Game,e.User).Bind("launcher"),GameVersionProbe.Read(e.Game)??new Version(42,0));LauncherComponents.Capture current=null;
   if(e.OwnedLaunch&&!vanilla){var components=e.OwnedComponents();current=components.CaptureCurrent(token,mode=="follow-server"?new string[0]:null);foreach(var row in current.Rows.Where(row=>row.Enabled))rows[row.Id]=row;evidence.Expect(()=>components.RequireCurrent(current));}
   byte[] buddy=null;
   if(e.OwnedLaunch&&!vanilla){LauncherComponents.Row row;if(rows.TryGetValue("ZombieBuddy",out row)){if(row.Warning!="")throw new IOException(row.Warning);buddy=LiveModDiscovery.BuddyBytes(row.Jar??Path.Combine(row.SourceRoot,"libs/ZombieBuddy.jar"));}}
   else if(!vanilla&&e.FrameworkConfigured){string path=Path.Combine(e.Game,"ZombieBuddy.jar");buddy=LiveModDiscovery.BuddyBytes(path);evidence.File(path,buddy);if(e.FrozenEnvironment!=null){var mapping=e.FrozenEnvironment.ModRoots.SingleOrDefault(value=>value.ModIds.Any(id=>Id(id)=="ZombieBuddy"));if(mapping!=null)rows["ZombieBuddy"]=new LauncherComponents.Row{Id="ZombieBuddy",Name="ZombieBuddy",SourceRoot=mapping.CopiedRoot,Enabled=true,installationComponent=true};}}
   var legacy=new HashSet<string>(e.OwnedLaunch&&!vanilla?e.OwnedComponents().LegacyEnabledIds():e.FrozenEnvironment==null?new string[0]:e.FrozenEnvironment.ActiveComponentIds??new string[0],StringComparer.Ordinal);
   var retained=new HashSet<string>(StringComparer.Ordinal);
   if(mode=="force-local"&&!vanilla){
    var catalog=SaveProfiles.SnapshotEntries(e,ids,warnings,budget,null,e.OwnedLaunch);var entries=catalog.Entries;var candidates=catalog.Candidates;
    foreach(string raw in ids){string id=Id(raw);var matches=entries.Where(value=>Id(value.id)==id).ToArray();LauncherComponents.Row row;rows.TryGetValue(id,out row);if(id=="ZombieBuddy"||LauncherComponents.KnownIds.Contains(id)||legacy.Contains(id)||matches.Any(entry=>entry.javaComponent||entry.requiresBuddy)||row!=null&&(row.Jar!=null||row.requiresBuddy||row.installationComponent))retained.Add(id);}
    foreach(var row in rows.Values.Where(row=>row.installationComponent||row.Jar!=null||row.requiresBuddy||LauncherComponents.KnownIds.Contains(row.Id)||legacy.Contains(row.Id)))retained.Add(row.Id);
    var pending=new Queue<string>(retained);while(pending.Count>0){token.ThrowIfCancellationRequested();string id=pending.Dequeue();if(id=="ZombieBuddy")continue;LauncherComponents.Row row;if(!rows.TryGetValue(id,out row)){var roots=candidates.Where(value=>value.Id==id).Select(value=>value.Root).Distinct(StringComparer.OrdinalIgnoreCase).ToArray();if(roots.Length!=1)throw new IOException(id+"：本地客户端组件没有唯一可用来源。");row=inspector.Inspect(roots[0],id,token);row.Enabled=true;rows[id]=row;}if(row.Warning!="")throw new IOException(row.Warning);foreach(string raw in row.Requires){string required=Id(raw);if(retained.Add(required))pending.Enqueue(required);}}
    if(retained.Contains("ZombieBuddy")&&buddy==null)throw new IOException("本地客户端组件需要已启用且可用的 ZombieBuddy 加载器。");
   }
   // Buddy remains a loader, not an extra mod injected into the server's list.
   retained.Remove("ZombieBuddy");var selected=rows.Values.Where(row=>retained.Contains(row.Id)).ToArray();var ordering=selected.Select(row=>new SaveProfiles.Entry{id=row.Id,requires=row.Requires.Where(value=>Id(value)!="ZombieBuddy").ToArray(),loadAfter=row.LoadAfter,loadBefore=row.LoadBefore,conflicts=row.Conflicts}).ToList();var requested=ids.Select(Id).Where(retained.Contains).Concat(retained).Distinct().ToArray();var sorted=ModConfigurations.Order(requested,ordering,new List<string>(),new HashSet<string>(requested));if(sorted.errors.Length>0){warnings.AddRange(sorted.errors);sorted.mods=requested;}warnings.AddRange(sorted.violations);
   if(buddy==null)warnings.Add("此配置未启用 Buddy 加载器；服务器 Java 模组无法授权或加载。");
   LauncherComponents.Row loader;if(rows.TryGetValue("ZombieBuddy",out loader))selected=selected.Concat(new[]{loader}).ToArray();
   foreach(var row in selected.Where(value=>value.Id!="ZombieBuddy")){if(row.Jar!=null){string jar=row.Jar,hash=row.Sha256;evidence.Expect(()=>{if(LauncherComponents.HashFile(jar,token)!=hash)throw new IOException("客户端 Java 文件已更新，请重新连接。");});}string root=row.SourceRoot,stamp=row.SourceEvidence;evidence.Expect(()=>{if(LauncherComponents.SourceStamp(root)!=stamp)throw new IOException("客户端组件来源已变化，请重新连接。");});}
   token.ThrowIfCancellationRequested();return new Plan{Mode=mode,Original=original,Buddy=buddy,Rows=selected,Ids=sorted.mods,Warnings=warnings.Concat(sorted.warnings).Distinct().ToArray(),Evidence=evidence};
  }
 }
 static partial class LaunchProfiles {
  static readonly UTF8Encoding ServerUtf8=new UTF8Encoding(false,true);
  static string ServerRecord(string key,params string[] values){return key+string.Concat(values.Select(value=>"\t"+Convert.ToBase64String(ServerUtf8.GetBytes(value))))+"\n";}
  internal static void ServerAtomic(string path,byte[] bytes){SnapshotFileSystem.NoReparse(path);SnapshotFileSystem.Directories.CreateDirectory(Path.GetDirectoryName(path));string temp=path+".s"+Guid.NewGuid().ToString("N").Substring(0,8);try{using(var output=new SnapshotFileSystem.Stream(temp,FileMode.CreateNew,FileAccess.Write,FileShare.None)){output.Write(bytes,0,bytes.Length);output.Flush(true);}if(SnapshotFileSystem.Files.Exists(path))SnapshotFileSystem.Files.Replace(temp,path,null);else SnapshotFileSystem.Files.Move(temp,path);}finally{if(SnapshotFileSystem.Files.Exists(temp))SnapshotFileSystem.Files.Delete(temp);}}
  static string ServerRuntimeRoot(Engine e){return Path.Combine(e.Data,"server-sessions",Key(e));}
  internal static string ServerReason(Engine e,bool busy,bool running){if(e.FrozenEnvironment==null)return LauncherLaunch.PreparationReason(e,busy,running);if(busy)return "此配置正在修改，请稍后连接。";if(running)return "游戏已经运行，请退出后再连接。";try{SaveEnvironmentRuntime.ValidateOwnedRuntime(e);e.GuardLaunch();return "";}catch(Exception error){return error.Message;}}
  static void StageServer(Engine e,ProfileLaunchRequest request){
   request.Cancellation.ThrowIfCancellationRequested();e.GuardLaunch();if(Pending(e))throw new IOException("上一次启动会话尚未恢复。");if((GameVersionProbe.Read(e.Game)??new Version(42,0)).Major!=42)throw new IOException("此游戏版本的服务器会话加载入口尚未核实。");
   string payload=Payload(request),nonce=payload.Split('\n')[1];var plan=ServerLaunchSelection.Capture(e,request.ServerComponents,request.Cancellation);string root=ServerRuntimeRoot(e),session=Path.Combine(root,"runtime","live-"+nonce.Substring(0,12)),bridge=Path.Combine(session,"bridge"),config=Path.Combine(session,"buddy");LauncherMaintenance.NoReparse(root);if(Directory.Exists(session))throw new IOException("服务器会话目录已存在。");foreach(string path in RequestFiles(e)){LauncherMaintenance.NoReparse(path);if(File.Exists(path))throw new IOException("存在上次启动请求，未覆盖。");}
   bool journaled=false;try{
    Directory.CreateDirectory(config);Directory.CreateDirectory(Path.Combine(session,"mods"));var files=BridgeFiles(bridge,false);foreach(var file in files){request.Cancellation.ThrowIfCancellationRequested();ServerAtomic(file.Key,file.Value);}string[] enabled=plan.Ids.Concat(new[]{ModId}).ToArray();ServerAtomic(Path.Combine(session,"mods/default.txt"),SaveProfiles.ReplaceDefaultMods(plan.Original,new[]{ModId}));ServerAtomic(Path.Combine(session,"mods/loaded.txt"),ServerUtf8.GetBytes(ModId));string agent=Path.Combine(session,"OrangeLive.jar");ServerAtomic(agent,BundledAssets.ReadOwnAsset("OrangeLive.jar"));
    var body=new StringBuilder("OZLLIVE1\n").Append(ServerRecord("game",e.Game)).Append(ServerRecord("user",e.User)).Append(ServerRecord("context",root)).Append(ServerRecord("choices",session)).Append(ServerRecord("vanilla","false")).Append(ServerRecord("server-components",plan.Mode));
    foreach(string id in enabled){body.Append(ServerRecord("managed",id));body.Append(ServerRecord("order",id));body.Append(ServerRecord("component",id));}foreach(var row in plan.Rows){if(row.Id=="ZombieBuddy"){body.Append(ServerRecord("managed",row.Id));body.Append(ServerRecord("component",row.Id));}body.Append(ServerRecord("selected",row.Id,row.SourceRoot));}body.Append(ServerRecord("selected",ModId,bridge));
    string buddyPath=Path.Combine(session,"ZombieBuddy.jar");if(plan.Buddy!=null){ServerAtomic(buddyPath,plan.Buddy);body.Append(ServerRecord("buddy",buddyPath,LiveModDiscovery.BuddyHash));}
    ServerAtomic(Path.Combine(config,"config.json"),ServerUtf8.GetBytes("{\"trusted_authors\":[],\"preload_mods\":{},\"auto_fix_mod_order\":false,\"fix_approval_dialog_cursor\":false}"));ServerAtomic(Path.Combine(config,"mod_approvals.json"),ServerUtf8.GetBytes(Json.Serialize(new{formatVersion=2,mods=plan.Rows.Where(row=>row.Jar!=null&&row.Decision!=null).Select(row=>new{id=row.Id,jar_hash=row.Sha256,decision=row.Decision.Value}).ToArray()})));
    string manifest=Path.Combine(session,"live.manifest");ServerAtomic(manifest,ServerUtf8.GetBytes(body.ToString()));string hash=DlssInstaller.HashFile(manifest);var args=new List<string>{"-Dozl.live.manifest="+manifest,"-Dozl.live.sha256="+hash,"-javaagent:"+agent};if(plan.Buddy!=null){args.Add("-Dzb.config_dir="+config);args.Add("-javaagent:"+buddyPath+"=prop_prefix=zb,policy=prompt");}
    args.AddRange(GameStartupComponent.PrepareServerSession(e,nonce,session,root));
    var prepared=new LiveModDiscovery.Session{ServerComponents=plan.Mode,Directory=session,Manifest=manifest,ManifestHash=hash,VmArguments=args.ToArray(),EnabledIds=enabled,SelectedRoots=plan.Rows.Select(row=>row.SourceRoot).Concat(new[]{bridge}).ToArray(),Warnings=plan.Warnings};
    var record=new ProfileSessionRecord{Game=e.Game,User=e.User,Token=Key(e),Nonce=nonce,Kind="server",ServerComponents=plan.Mode,ServerRuntimeRoot=root,ConfigurationRoot=e.OwnedLaunch?e.OwnedConfiguration.Root:null,State="prepared",CreatedUtc=DateTime.UtcNow.ToString("o"),Original=plan.Original==null?null:Convert.ToBase64String(plan.Original),AppliedHash=DlssInstaller.Hash(plan.Original??new byte[0]),SessionDirectory=session,BridgeDirectory=bridge,SessionVmArguments=prepared.VmArguments,CaptureEndpoint=request.Host+":"+request.Port};try{record.CaptureRevision=ServerWorkshopCatalog.Revision(e.Data,record.CaptureEndpoint);}catch{record.CaptureRevision=null;}foreach(var file in files)record.Files[file.Key]=DlssInstaller.Hash(file.Value);
    ValidateServerRecord(e,record);plan.Evidence.Validate(()=>request.Cancellation.ThrowIfCancellationRequested());if(request.ValidateBeforeStage!=null)request.ValidateBeforeStage();request.Cancellation.ThrowIfCancellationRequested();ServerAtomic(Journal(e),ServerUtf8.GetBytes(Json.Serialize(record)));journaled=true;Directory.CreateDirectory(Path.Combine(e.User,"Lua"));PrivateRequest(LuaFile(e,RequestName),payload);ServerAtomic(LuaFile(e,StatusName),ServerUtf8.GetBytes("prepared\n"));e.LiveSession=prepared;
   }catch{if(journaled)Recover(e,true);else if(Directory.Exists(session))RemoveServerRuntime(e,session);throw;}
  }
  static void ValidateServerRecord(Engine e,ProfileSessionRecord record){if(record.Kind!="server"||ServerLaunchSelection.Mode(record.ServerComponents)!=record.ServerComponents||!VersionLibrary.Same(record.ServerRuntimeRoot,ServerRuntimeRoot(e))||!System.Text.RegularExpressions.Regex.IsMatch(record.Nonce??"","^[a-f0-9]{32}$")||!VersionLibrary.Same(record.SessionDirectory,Path.Combine(ServerRuntimeRoot(e),"runtime","live-"+record.Nonce.Substring(0,12)))||!VersionLibrary.Same(record.BridgeDirectory,Path.Combine(record.SessionDirectory,"bridge")))throw new IOException("服务器会话记录不属于此配置。");// Recovery describes the release that created this session. Do not read or
   // compare the current release assets: a newer UI and an assetless cached
   // watcher must both be able to retire the older temporary runtime.
   var expected=new[]{Path.Combine(record.BridgeDirectory,"common","mod.info"),Path.Combine(record.BridgeDirectory,"42","mod.info"),Path.Combine(record.BridgeDirectory,"42","media","lua","client","OrangeLaunchBridge.lua")};if(record.Files==null||record.Files.Count!=expected.Length||expected.Any(path=>!record.Files.ContainsKey(path)||!System.Text.RegularExpressions.Regex.IsMatch(record.Files[path]??"","^[A-F0-9]{64}$")))throw new IOException("服务器会话桥接记录无效。");LauncherMaintenance.NoReparse(record.SessionDirectory);}
  static void RemoveServerRuntime(Engine e,string session){if(!VersionLibrary.Same(Path.GetDirectoryName(Path.GetFullPath(session)),Path.Combine(ServerRuntimeRoot(e),"runtime"))||!System.Text.RegularExpressions.Regex.IsMatch(Path.GetFileName(session),"^live-[a-f0-9]{12}$"))throw new IOException("服务器会话清理目录无效。");LauncherMaintenance.NoReparse(session);if(!Directory.Exists(session))return;VerifyServerTree(session);SnapshotFileSystem.Directories.Delete(session,true);}
  static void VerifyServerTree(string root){SnapshotFileSystem.NoReparse(root);foreach(string child in SnapshotFileSystem.Directories.EnumerateFileSystemEntries(root)){SnapshotFileSystem.NoReparse(child);if((SnapshotFileSystem.Files.GetAttributes(child)&FileAttributes.Directory)!=0)VerifyServerTree(child);}}
  internal static ProfileSessionRecord ServerSession(Engine e,string nonce){if(!Pending(e))return null;var record=Load(e);return record.ServerRuntimeRoot!=null&&record.Nonce==nonce?record:null;}
  static string RecoverServer(Engine e,ProfileSessionRecord record){ValidateServerRecord(e,record);ClearRequest(e);RemoveServerRuntime(e,record.SessionDirectory);File.Delete(Journal(e));e.LiveSession=null;return "已清理本次服务器会话，保留原启动配置与快照。";}
  static System.Diagnostics.ProcessStartInfo ServerStartInfo(Engine e){
   System.Diagnostics.ProcessStartInfo start;string[] source;
   if(e.OwnedLaunch){int major=(GameVersionProbe.Read(e.Game)??new Version(42,0)).Major;start=e.OwnedConfiguration.BuildStartInfo(major);source=e.OwnedConfiguration.StockArguments(major);}
   else{var config=new JavaScriptSerializer{MaxJsonLength=4194304}.Deserialize<Dictionary<string,object>>(File.ReadAllText(e.Config,ServerUtf8));source=FrozenJavaArguments(config,CurrentWindowsVersion());start=new System.Diagnostics.ProcessStartInfo(Path.Combine(e.Game,"jre64/bin/java.exe")){UseShellExecute=false,CreateNoWindow=true,WorkingDirectory=e.Game};start.EnvironmentVariables["SteamAppId"]="108600";start.EnvironmentVariables["SteamGameId"]="108600";start.EnvironmentVariables["PATH"]=Path.Combine(e.Game,"jre64/bin")+";"+e.Game+";"+(start.EnvironmentVariables["PATH"]??"");}
   var args=new List<string>();foreach(string arg in source){if(arg.StartsWith("-Dozl.environment",StringComparison.Ordinal)||arg==SaveEnvironmentRuntime.Argument||arg==GameStartupComponent.Argument||arg.StartsWith("-Dozl.startup.context=",StringComparison.Ordinal)||arg.StartsWith("-Dzb.",StringComparison.Ordinal)||arg.StartsWith("-Dzombie_buddy.",StringComparison.Ordinal)||BuddyLaunchArguments.Classify(arg)==BuddyArgumentKind.Known)continue;args.Add(arg);}int cp=args.IndexOf("-cp");if(cp<0)throw new IOException("服务器启动参数缺少 classpath。");args.InsertRange(0,e.LiveSession.VmArguments);if(!args.Any(arg=>arg.StartsWith("-cachedir=",StringComparison.Ordinal)))args.Add("-cachedir="+e.User);start.Arguments=string.Join(" ",args.Select(LauncherConfiguration.QuoteArgument));foreach(string key in new[]{"JAVA_TOOL_OPTIONS","_JAVA_OPTIONS","JDK_JAVA_OPTIONS","ZB_VERBOSITY"})start.EnvironmentVariables.Remove(key);return start;
  }
